mapper.select:
select r.*, exists ( select 1 from s_product_sku_review_reply rr where rr.deleted = 0 and rr.review_id = r.id ) as is_replied, ( select rr.sender_type from s_product_sku_review_reply rr where rr.deleted = 0 and rr.review_id = r.id order by rr.create_time desc, rr.id desc limit 1 ) as last_reply_sender_type from s_product_sku_review r where r.deleted = 0
and r.mch_id = #{mchId}
and r.shop_id = #{shopId}
and r.spu_id = #{query.spuId}
and r.shop_id = #{query.shopId}
and r.is_visible = #{query.isVisible}
and exists ( select 1 from s_product_sku_review_image i where i.deleted = 0 and i.review_id = r.id )
and exists ( select 1 from s_product_sku_review_reply rr where rr.deleted = 0 and rr.review_id = r.id )
and not exists ( select 1 from s_product_sku_review_reply rr where rr.deleted = 0 and rr.review_id = r.id )
and r.create_time >= #{query.beginTime}
and r.create_time <= #{query.endTime}
and r.overall_rating >= 4
and r.overall_rating = 3
and r.overall_rating <= 2
order by r.create_time desc
